/// The `GraphemeBreak` of a character.
pub fn grapheme_break(character: char) -> GraphemeBreak {
	GraphemeBreak::from_ordinal(crate::lookup(GRAPHEME_BREAK, character as u32))
}

/// The `WordBreak` property. Variant 0 is the value a character the UCD does not mention takes.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
#[repr(u8)]
pub enum WordBreak {
	Other = 0,
	CR = 1,
	LF = 2,
	Newline = 3,
	Extend = 4,
	ZWJ = 5,
	RegionalIndicator = 6,
	Format = 7,
	Katakana = 8,
	HebrewLetter = 9,
	ALetter = 10,
	SingleQuote = 11,
	DoubleQuote = 12,
	MidNumLet = 13,
	MidLetter = 14,
	MidNum = 15,
	Numeric = 16,
	ExtendNumLet = 17,
	WSegSpace = 18,
}

impl WordBreak {
	/// The value an ordinal names. Out of range is the default, which cannot happen for a table
	/// this generator wrote and is answered rather than panicked on for the one that reads bytes.
	pub const fn from_ordinal(ordinal: u8) -> Self {
		match ordinal {
			1 => Self::CR,
			2 => Self::LF,
			3 => Self::Newline,
			4 => Self::Extend,
			5 => Self::ZWJ,
			6 => Self::RegionalIndicator,
			7 => Self::Format,
			8 => Self::Katakana,
			9 => Self::HebrewLetter,
			10 => Self::ALetter,
			11 => Self::SingleQuote,
			12 => Self::DoubleQuote,
			13 => Self::MidNumLet,
			14 => Self::MidLetter,
			15 => Self::MidNum,
			16 => Self::Numeric,
			17 => Self::ExtendNumLet,
			18 => Self::WSegSpace,
			_ => Self::Other,
		}
	}

	/// The property's name as the UCD spells it.
	pub const fn ucd_name(self) -> &'static str {
		match self {
			Self::Other => "Other",
			Self::CR => "CR",
			Self::LF => "LF",
			Self::Newline => "Newline",
			Self::Extend => "Extend",
			Self::ZWJ => "ZWJ",
			Self::RegionalIndicator => "Regional_Indicator",
			Self::Format => "Format",
			Self::Katakana => "Katakana",
			Self::HebrewLetter => "Hebrew_Letter",
			Self::ALetter => "ALetter",
			Self::SingleQuote => "Single_Quote",
			Self::DoubleQuote => "Double_Quote",
			Self::MidNumLet => "MidNumLet",
			Self::MidLetter => "MidLetter",
			Self::MidNum => "MidNum",
			Self::Numeric => "Numeric",
			Self::ExtendNumLet => "ExtendNumLet",
			Self::WSegSpace => "WSegSpace",
		}
	}
}

