/// The `IndicSyllabic` of a character.
pub fn indic_syllabic(character: char) -> IndicSyllabic {
	IndicSyllabic::from_ordinal(crate::lookup(INDIC_SYLLABIC, character as u32))
}

/// The `IndicPositional` property. Variant 0 is the value a character the UCD does not mention takes.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
#[repr(u8)]
pub enum IndicPositional {
	NA = 0,
	Right = 1,
	Left = 2,
	VisualOrderLeft = 3,
	LeftAndRight = 4,
	Top = 5,
	Bottom = 6,
	TopAndBottom = 7,
	TopAndRight = 8,
	TopAndLeft = 9,
	TopAndLeftAndRight = 10,
	BottomAndRight = 11,
	BottomAndLeft = 12,
	TopAndBottomAndRight = 13,
	TopAndBottomAndLeft = 14,
	Overstruck = 15,
}

impl IndicPositional {
	/// The value an ordinal names. Out of range is the default, which cannot happen for a table
	/// this generator wrote and is answered rather than panicked on for the one that reads bytes.
	pub const fn from_ordinal(ordinal: u8) -> Self {
		match ordinal {
			1 => Self::Right,
			2 => Self::Left,
			3 => Self::VisualOrderLeft,
			4 => Self::LeftAndRight,
			5 => Self::Top,
			6 => Self::Bottom,
			7 => Self::TopAndBottom,
			8 => Self::TopAndRight,
			9 => Self::TopAndLeft,
			10 => Self::TopAndLeftAndRight,
			11 => Self::BottomAndRight,
			12 => Self::BottomAndLeft,
			13 => Self::TopAndBottomAndRight,
			14 => Self::TopAndBottomAndLeft,
			15 => Self::Overstruck,
			_ => Self::NA,
		}
	}

	/// The property's name as the UCD spells it.
	pub const fn ucd_name(self) -> &'static str {
		match self {
			Self::NA => "NA",
			Self::Right => "Right",
			Self::Left => "Left",
			Self::VisualOrderLeft => "Visual_Order_Left",
			Self::LeftAndRight => "Left_And_Right",
			Self::Top => "Top",
			Self::Bottom => "Bottom",
			Self::TopAndBottom => "Top_And_Bottom",
			Self::TopAndRight => "Top_And_Right",
			Self::TopAndLeft => "Top_And_Left",
			Self::TopAndLeftAndRight => "Top_And_Left_And_Right",
			Self::BottomAndRight => "Bottom_And_Right",
			Self::BottomAndLeft => "Bottom_And_Left",
			Self::TopAndBottomAndRight => "Top_And_Bottom_And_Right",
			Self::TopAndBottomAndLeft => "Top_And_Bottom_And_Left",
			Self::Overstruck => "Overstruck",
		}
	}
}

