/// The `IndicPositional` of a character.
pub fn indic_positional(character: char) -> IndicPositional {
	IndicPositional::from_ordinal(crate::lookup(INDIC_POSITIONAL, character as u32))
}

/// The `JoiningType` property. Variant 0 is the value a character the UCD does not mention takes.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
#[repr(u8)]
pub enum JoiningType {
	U = 0,
	C = 1,
	D = 2,
	L = 3,
	R = 4,
	T = 5,
}

impl JoiningType {
	/// The value an ordinal names. Out of range is the default, which cannot happen for a table
	/// this generator wrote and is answered rather than panicked on for the one that reads bytes.
	pub const fn from_ordinal(ordinal: u8) -> Self {
		match ordinal {
			1 => Self::C,
			2 => Self::D,
			3 => Self::L,
			4 => Self::R,
			5 => Self::T,
			_ => Self::U,
		}
	}

	/// The property's name as the UCD spells it.
	pub const fn ucd_name(self) -> &'static str {
		match self {
			Self::U => "U",
			Self::C => "C",
			Self::D => "D",
			Self::L => "L",
			Self::R => "R",
			Self::T => "T",
		}
	}
}

