/// The `JoiningType` of a character.
pub fn joining_type(character: char) -> JoiningType {
	match crate::lookup_run(JOINING_TYPE, character as u32) {
		Some(ordinal) => JoiningType::from_ordinal(ordinal),
		None => match general_category(character) {
			GeneralCategory::Mn | GeneralCategory::Me | GeneralCategory::Cf => JoiningType::T,
			_ => JoiningType::U,
		},
	}
}

