/// The `GeneralCategory` of a character.
pub fn general_category(character: char) -> GeneralCategory {
	GeneralCategory::from_ordinal(crate::lookup(GENERAL_CATEGORY, character as u32))
}

/// The `IndicConjunctBreak` property. Variant 0 is the value a character the UCD does not mention takes.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
#[repr(u8)]
pub enum IndicConjunctBreak {
	None = 0,
	Linker = 1,
	Consonant = 2,
	Extend = 3,
}

impl IndicConjunctBreak {
	/// The value an ordinal names. Out of range is the default, which cannot happen for a table
	/// this generator wrote and is answered rather than panicked on for the one that reads bytes.
	pub const fn from_ordinal(ordinal: u8) -> Self {
		match ordinal {
			1 => Self::Linker,
			2 => Self::Consonant,
			3 => Self::Extend,
			_ => Self::None,
		}
	}

	/// The property's name as the UCD spells it.
	pub const fn ucd_name(self) -> &'static str {
		match self {
			Self::None => "None",
			Self::Linker => "Linker",
			Self::Consonant => "Consonant",
			Self::Extend => "Extend",
		}
	}
}

