/// The `IndicConjunctBreak` of a character.
pub fn indic_conjunct_break(character: char) -> IndicConjunctBreak {
	IndicConjunctBreak::from_ordinal(crate::lookup(INDIC_CONJUNCT_BREAK, character as u32))
}

/// The `EastAsianWidth` property. Variant 0 is the value a character the UCD does not mention takes.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
#[repr(u8)]
pub enum EastAsianWidth {
	N = 0,
	A = 1,
	F = 2,
	H = 3,
	Na = 4,
	W = 5,
}

impl EastAsianWidth {
	/// The value an ordinal names. Out of range is the default, which cannot happen for a table
	/// this generator wrote and is answered rather than panicked on for the one that reads bytes.
	pub const fn from_ordinal(ordinal: u8) -> Self {
		match ordinal {
			1 => Self::A,
			2 => Self::F,
			3 => Self::H,
			4 => Self::Na,
			5 => Self::W,
			_ => Self::N,
		}
	}

	/// The property's name as the UCD spells it.
	pub const fn ucd_name(self) -> &'static str {
		match self {
			Self::N => "N",
			Self::A => "A",
			Self::F => "F",
			Self::H => "H",
			Self::Na => "Na",
			Self::W => "W",
		}
	}
}

