/// The `EastAsianWidth` of a character.
pub fn east_asian_width(character: char) -> EastAsianWidth {
	EastAsianWidth::from_ordinal(crate::lookup(EAST_ASIAN_WIDTH, character as u32))
}

/// The `BidiClass` property. Variant 0 is the value a character the UCD does not mention takes.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Debug)]
#[repr(u8)]
pub enum BidiClass {
	L = 0,
	R = 1,
	AL = 2,
	EN = 3,
	ES = 4,
	ET = 5,
	AN = 6,
	CS = 7,
	NSM = 8,
	BN = 9,
	B = 10,
	S = 11,
	WS = 12,
	ON = 13,
	LRE = 14,
	LRO = 15,
	RLE = 16,
	RLO = 17,
	PDF = 18,
	LRI = 19,
	RLI = 20,
	FSI = 21,
	PDI = 22,
}

impl BidiClass {
	/// The value an ordinal names. Out of range is the default, which cannot happen for a table
	/// this generator wrote and is answered rather than panicked on for the one that reads bytes.
	pub const fn from_ordinal(ordinal: u8) -> Self {
		match ordinal {
			1 => Self::R,
			2 => Self::AL,
			3 => Self::EN,
			4 => Self::ES,
			5 => Self::ET,
			6 => Self::AN,
			7 => Self::CS,
			8 => Self::NSM,
			9 => Self::BN,
			10 => Self::B,
			11 => Self::S,
			12 => Self::WS,
			13 => Self::ON,
			14 => Self::LRE,
			15 => Self::LRO,
			16 => Self::RLE,
			17 => Self::RLO,
			18 => Self::PDF,
			19 => Self::LRI,
			20 => Self::RLI,
			21 => Self::FSI,
			22 => Self::PDI,
			_ => Self::L,
		}
	}

	/// The property's name as the UCD spells it.
	pub const fn ucd_name(self) -> &'static str {
		match self {
			Self::L => "L",
			Self::R => "R",
			Self::AL => "AL",
			Self::EN => "EN",
			Self::ES => "ES",
			Self::ET => "ET",
			Self::AN => "AN",
			Self::CS => "CS",
			Self::NSM => "NSM",
			Self::BN => "BN",
			Self::B => "B",
			Self::S => "S",
			Self::WS => "WS",
			Self::ON => "ON",
			Self::LRE => "LRE",
			Self::LRO => "LRO",
			Self::RLE => "RLE",
			Self::RLO => "RLO",
			Self::PDF => "PDF",
			Self::LRI => "LRI",
			Self::RLI => "RLI",
			Self::FSI => "FSI",
			Self::PDI => "PDI",
		}
	}
}

