/// The `BidiClass` of a character.
pub fn bidi_class(character: char) -> BidiClass {
	// A code point the records do not mention takes its BLOCK's default, which is `R` or `AL`
	// in the right-to-left blocks and `L` elsewhere - see `BIDI_CLASS_DEFAULTS`.
	match crate::lookup_run(BIDI_CLASS, character as u32) {
		Some(ordinal) => BidiClass::from_ordinal(ordinal),
		None => BidiClass::from_ordinal(crate::lookup(BIDI_CLASS_DEFAULTS, character as u32)),
	}
}

